<?php require 'app.php';$token=preg_replace('/[^a-f0-9]/','',strtolower($_GET['token']??''));$q=db()->prepare("SELECT st.first_name,st.last_name,st.admission_number,st.status student_status,c.name class_name,c.stream,s.name school_name,ic.status card_status FROM id_cards ic JOIN students st ON st.id=ic.student_id AND st.school_id=ic.school_id JOIN schools s ON s.id=ic.school_id LEFT JOIN classes c ON c.id=st.class_id WHERE ic.qr_token=? LIMIT 1");$q->execute([$token]);$r=$q->fetch();$ok=$r&&$r['card_status']==='active'&&$r['student_status']==='active';?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student card verification</title><link rel="stylesheet" href="assets/style.css"></head><body><main style="max-width:600px;margin:40px auto;padding:20px;background:white"><h1>Student ID Verification</h1><?php if($ok):?><h2 style="color:green">Valid card</h2><p>School: <?=h($r['school_name'])?></p><p>Student: <?=h($r['first_name'].' '.$r['last_name'])?></p><p>Admission number: <?=h($r['admission_number'])?></p><p>Class: <?=h(($r['class_name']??'').' '.($r['stream']??''))?></p><?php else:?><h2 style="color:#a22">Card not valid</h2><?php endif;?></main></body></html>
